function crhRequest(array &$session,?array $post=null,string $route='club_rewards_admin.php'):array {$c=curl_init('http://127.0.0.1:18086/'.$route);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_COOKIE=>$session['cookie'],CURLOPT_TIMEOUT=>20,CURLOPT_PROXY=>'',CURLOPT_PROTOCOLS=>CURLPROTO_HTTP,CURLOPT_HEADERFUNCTION=>static function($curl,string $line)use(&$session):int{if(preg_match('/^Set-Cookie:\s*(EVIDENCESESSID=[^;]+)/i',$line,$m))$session['cookie']=$m[1];return strlen($line);}]);if($post!==null){$post+=['csrf_token'=>$session['csrf']];curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,http_build_query($post));}$body=curl_exec($c);$status=(int)curl_getinfo($c,CURLINFO_RESPONSE_CODE);$error=curl_error($c);curl_close($c);if(!is_string($body)||$status===0||$status>=500)throw new RuntimeException('HTTP '.$status.' '.$error.' '.substr((string)$body,0,500));return ['status'=>$status,'body'=>$body];}
