$settledView=crhRequest($finance,null,'club_rewards_admin.php?reward_id='.$claim.'&reward_settlement=settled');crhCheck($settledView['status']===200&&str_contains($settledView['body'],'id="reward-'.$claim.'"'),'Settled filter finds approved fully paid claim after actual repayment');
$dueView=crhRequest($coach,null,'club_rewards_admin.php?reward_id='.$claim.'&reward_settlement=due');crhCheck($dueView['status']===200&&!str_contains($dueView['body'],'id="reward-'.$claim.'"'),'Settled claim leaves outstanding list for own coach');
$pdo->prepare("DELETE FROM staff_user_positions WHERE trainer_id=? AND position_code='finance_manager'")->execute([$actors['finance_manager']]);crhCheck(crhRequest($finance,$pay)['status']===403,'Revoked stale finance role cannot replay payout');
